            </div>
            {logs.length > 0 && !isProcessing && (
              <button 
                onClick={() => setLogs([])}
                className="text-[10px] font-bold text-slate-500 hover:text-white transition-colors uppercase tracking-widest"
              >
                Clear Console
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

